def choose_move(observation):
    def g(key, default=None):
        return observation.get(key, default) if hasattr(observation, "get") else default

    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except:
                return default
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_of(items, scorer, prefer_min=True):
        best_item = None
        best_score = None
        for it in items:
            try:
                s = scorer(it)
            except:
                continue
            if best_item is None:
                best_item, best_score = it, s
            else:
                if (prefer_min and s < best_score) or ((not prefer_min) and s > best_score):
                    best_item, best_score = it, s
        return best_item

    sx, sy = pos(g("self_position"))
    ox, oy = pos(g("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    env = g("environment_name", "resource_collection")

    if env == "pursuit_evasion":
        role = g("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = g("grid_width", 0)
        h = g("grid_height", 0)
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(0, 0), (0, 9), (9, 0), (9, 9)]
        target = best_of(corners, lambda c: manhattan(c, opp_pos), prefer_min=False)
        return step_toward(self_pos, target if target is not None else (0, 0))

    if env == "territory_control":
        candidates = g("unclaimed_cells") or g("opponent_territory") or g("neutral_cells") or []
        if candidates:
            target = best_of(candidates, lambda c: manhattan(pos(c), self_pos), prefer_min=True)
            if target is not None:
                return step_toward(self_pos, pos(target))
        # fallback: move toward opponent or center if known
        w = g("grid_width", 0)
        h = g("grid_height", 0)
        if w and h:
            center = (w // 2, h // 2)
            return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    resources = g("resources") or g("resource_positions") or []
    if resources:
        target = best_of(resources, lambda r: manhattan(pos(r), self_pos), prefer_min=True)
        if target is not None:
            return step_toward(self_pos, pos(target))

    # General fallback: bias toward opponent if close, otherwise toward center / origin.
    w = g("grid_width", 0)
    h = g("grid_height", 0)
    if w and h:
        center = (w // 2, h // 2)
        if manhattan(self_pos, opp_pos) <= manhattan(center, opp_pos):
            return step_toward(self_pos, opp_pos)
        return step_toward(self_pos, center)

    return step_toward(self_pos, opp_pos)

